"arrest":{a:[{tr:"i. tutuklama; f. tutuklamak",ex:"Police carried out a dramatic arrest of the suspect after weeks of surveillance.",exTr:"Polis, haftalarca süren gözetimin ardından şüpheliyi çarpıcı bir operasyonla tutukladı.",yz:4},{tr:"f. durdurmak, yavaşlatmak (bir süreci)",ex:"New regulations were introduced to arrest the rapid decline of the region's fish population.",exTr:"Bölgedeki balık popülasyonunun hızlı düşüşünü durdurmak için yeni düzenlemeler getirildi.",yz:3}]},
"bible":{a:[{tr:"i. İncil, Kutsal Kitap",ex:"The museum displayed a rare handwritten Bible dating back to the fifteenth century.",exTr:"Müze, on beşinci yüzyıla uzanan nadir bir el yazması İncil sergiledi.",yz:3},{tr:"i. başvuru kitabı, temel kaynak (bir alanın)",ex:"This cookbook is considered the bible of French cuisine among professional chefs.",exTr:"Bu yemek kitabı, profesyonel şefler arasında Fransız mutfağının başvuru kitabı olarak kabul edilir.",yz:2}]},
"breath":{a:[{tr:"i. nefes, soluk",ex:"She took a deep breath before stepping onto the stage to deliver her speech.",exTr:"Konuşmasını yapmak üzere sahneye çıkmadan önce derin bir nefes aldı."}]},
"catastrophic":{a:[{tr:"s. feci, yıkıcı, felaket getiren",ex:"The earthquake caused catastrophic damage to hospitals and schools across the region.",exTr:"Deprem, bölgedeki hastanelere ve okullara yıkıcı hasar verdi."}]},
"chest":{a:[{tr:"i. göğüs",ex:"The doctor listened carefully to the patient's chest to check for signs of infection.",exTr:"Doktor, enfeksiyon belirtilerini kontrol etmek için hastanın göğsünü dikkatle dinledi.",yz:4},{tr:"i. sandık, çekmeceli dolap",ex:"Her grandmother kept old letters and photographs locked inside a wooden chest in the attic.",exTr:"Büyükannesi, eski mektupları ve fotoğrafları tavan arasındaki ahşap bir sandığın içinde kilitli tutardı.",yz:2}]},
"contest":{a:[{tr:"i. yarışma, mücadele; f. itiraz etmek, mücadele etmek",ex:"Thousands of students entered the science contest hoping to win a university scholarship.",exTr:"Binlerce öğrenci, üniversite bursu kazanmayı umarak bilim yarışmasına katıldı."}]},
"definitive":{a:[{tr:"s. kesin, nihai, kesinleşmiş",ex:"Scientists have not yet reached a definitive conclusion about the drug's long-term side effects.",exTr:"Bilim insanları, ilacın uzun vadeli yan etkileri hakkında henüz kesin bir sonuca ulaşmadı."}]},
