"denominator":{a:[{tr:"i. payda (kesirde)",ex:"The teacher explained how to find a common denominator before adding two fractions.",exTr:"Öğretmen, iki kesri toplamadan önce ortak paydanın nasıl bulunacağını açıkladı."}]},
"depicted":{a:[{tr:"s. tasvir edilen, betimlenen, resmedilen",ex:"The events depicted in the documentary shocked audiences around the world.",exTr:"Belgeselde tasvir edilen olaylar, dünyanın dört bir yanındaki izleyicileri şoke etti."}]},
"donate":{a:[{tr:"f. bağışlamak",ex:"Local businesses donated food and clothing to families affected by the recent flooding.",exTr:"Yerel işletmeler, son sel felaketinden etkilenen ailelere gıda ve giysi bağışladı."}]},
"levy":{a:[{tr:"i. vergi, harç; f. vergi koymak, toplamak",ex:"The city council decided to levy an additional tax on plastic packaging to reduce waste.",exTr:"Belediye meclisi, atığı azaltmak için plastik ambalaja ek bir vergi koymaya karar verdi."}]},
