"mass-produce":{a:[{tr:"f. seri üretmek, toplu üretmek",ex:"Factories began to mass-produce affordable vaccines once the formula was approved for public use.",exTr:"Formül halk kullanımı için onaylandıktan sonra fabrikalar uygun fiyatlı aşıları seri üretmeye başladı."}]},
"millimeter":{a:[{tr:"i. milimetre",ex:"The surgeon adjusted the instrument by a single millimeter to avoid damaging surrounding tissue.",exTr:"Cerrah, çevredeki dokuya zarar vermemek için aleti yalnızca bir milimetre ayarladı."}]},
"morphological":{a:[{tr:"s. biçimbilimsel, yapısal, şekle ilişkin",ex:"Biologists noted significant morphological differences between the two beetle species despite their close genetic relationship.",exTr:"Biyologlar, yakın genetik ilişkilerine rağmen iki böcek türü arasında belirgin biçimbilimsel farklılıklar olduğunu belirtti."}]},
"one-party":{a:[{tr:"s. tek partili",ex:"Historians studied how the one-party system maintained control over the country's media for decades.",exTr:"Tarihçiler, tek partili sistemin ülkenin medyası üzerindeki denetimini on yıllar boyunca nasıl sürdürdüğünü inceledi."}]},
"orbit":{a:[{tr:"i. yörünge; f. yörüngede dönmek",ex:"The satellite was launched into orbit to collect data on global temperature changes.",exTr:"Uydu, küresel sıcaklık değişimleri hakkında veri toplamak için yörüngeye fırlatıldı."}]},
"oyster":{a:[{tr:"i. istiridye",ex:"The restaurant is famous for serving fresh oysters harvested daily from the nearby bay.",exTr:"Restoran, yakındaki körfezden her gün toplanan taze istiridyeleri sunmasıyla ünlüdür."}]},
"penetrate":{a:[{tr:"f. nüfuz etmek, içine işlemek, sızmak",ex:"Sunlight can barely penetrate the dense canopy of the tropical rainforest.",exTr:"Güneş ışığı, tropikal yağmur ormanının yoğun tepe örtüsüne neredeyse hiç nüfuz edemez."}]},
"plaza":{a:[{tr:"i. meydan; alışveriş merkezi",ex:"Street musicians gathered in the plaza every evening to perform for passing tourists.",exTr:"Sokak müzisyenleri, geçen turistler için performans sergilemek üzere her akşam meydanda toplandı."}]},
"polygraph":{a:[{tr:"i. yalan makinesi, poligraf",ex:"The suspect voluntarily agreed to take a polygraph test to prove his innocence.",exTr:"Şüpheli, masumiyetini kanıtlamak için gönüllü olarak bir yalan makinesi testine girmeyi kabul etti."}]},
"poultry":{a:[{tr:"i. kümes hayvanları (tavuk, hindi vb.)",ex:"The farm exports fresh poultry to restaurants throughout the region every week.",exTr:"Çiftlik, her hafta bölgedeki restoranlara taze kümes hayvanları ihraç ediyor."}]},
"presidential":{a:[{tr:"s. başkanlığa ait, başkanlık",ex:"Voter turnout was unusually high during the last presidential election in the country.",exTr:"Ülkedeki son başkanlık seçiminde seçmen katılımı alışılmadık derecede yüksekti."}]},
"prevalent":{a:[{tr:"s. yaygın, hâkim",ex:"Obesity has become increasingly prevalent among children in industrialized countries over the past thirty years.",exTr:"Son otuz yılda, sanayileşmiş ülkelerdeki çocuklar arasında obezite giderek daha yaygın hale gelmiştir."}]},
"repetitive":{a:[{tr:"s. tekrarlayan, monoton, yeknesak",ex:"Factory workers often complain that repetitive tasks increase the risk of joint injuries.",exTr:"Fabrika işçileri, tekrarlayan görevlerin eklem yaralanma riskini artırdığından sıkça şikayet eder."}]},
"self-confidence":{a:[{tr:"i. özgüven, kendine güven",ex:"Participating in team sports helped the shy teenager gradually build self-confidence.",exTr:"Takım sporlarına katılmak, çekingen gencin özgüvenini yavaş yavaş geliştirmesine yardımcı oldu."}]},
"shame":{a:[{tr:"i. utanç, ayıp; f. utandırmak",ex:"He felt a deep sense of shame after forgetting his sister's birthday for the second year.",exTr:"İkinci yıl da kız kardeşinin doğum gününü unuttuktan sonra derin bir utanç duydu."}]},
"superstition":{a:[{tr:"i. batıl inanç",ex:"Despite modern education, some old superstitions about black cats still persist in rural areas.",exTr:"Modern eğitime rağmen, kara kediler hakkındaki bazı eski batıl inançlar kırsal bölgelerde hâlâ sürmektedir."}]},
"suspension":{a:[{tr:"i. askıya alma, geçici uzaklaştırma",ex:"The student received a two-week suspension for repeatedly violating the school's dress code.",exTr:"Öğrenci, okulun kıyafet kurallarını tekrar tekrar ihlal ettiği için iki haftalık uzaklaştırma cezası aldı."}]},
"swear":{a:[{tr:"f. yemin etmek, ant içmek",ex:"Witnesses must swear to tell the truth before testifying in court.",exTr:"Tanıklar, mahkemede ifade vermeden önce doğruyu söyleyeceklerine yemin etmelidir.",yz:4},{tr:"f. küfretmek, sövmek",ex:"The coach warned players not to swear at officials during the championship match.",exTr:"Antrenör, oyunculara şampiyonluk maçı sırasında hakemlere küfretmemeleri konusunda uyardı.",yz:2}]},
"tall":{a:[{tr:"s. uzun boylu, yüksek",ex:"The new office building is the tallest structure in the entire downtown skyline.",exTr:"Yeni ofis binası, tüm şehir merkezi silüetindeki en yüksek yapıdır."}]},
"unified":{a:[{tr:"s. birleşik, birleştirilmiş, bütünleşik",ex:"The new software platform created a unified system for managing all hospital patient records.",exTr:"Yeni yazılım platformu, tüm hastane hasta kayıtlarını yönetmek için birleşik bir sistem oluşturdu."}]},
