"cherry":{a:[{tr:"i. kiraz; s. kiraz kırmızısı",ex:"Farmers in the valley harvest cherry crops each summer before exporting them across the region.",exTr:"Vadideki çiftçiler, bölgeye ihraç etmeden önce her yaz kiraz mahsulünü hasat eder."}]},
"counsel":{a:[{tr:"i. öğüt, tavsiye; f. öğüt vermek, tavsiye etmek",ex:"The lawyer's counsel helped the young entrepreneur avoid several costly legal mistakes.",exTr:"Avukatın verdiği öğüt, genç girişimcinin birkaç maliyetli hukuki hatadan kaçınmasına yardımcı oldu."}]},
"crush":{a:[{tr:"f. ezmek, parçalamak",ex:"The heavy machinery can crush large rocks into small pieces of gravel.",exTr:"Ağır iş makineleri büyük kayaları küçük çakıl parçalarına dönüştürecek şekilde ezebilir.",yz:4},{tr:"i. (argo) gönül tutulması, geçici aşk",ex:"Many teenagers experience their first crush during middle school without fully understanding the feeling.",exTr:"Birçok genç, bu duyguyu tam olarak anlamadan ortaokul yıllarında ilk gönül tutulmasını yaşar.",yz:1}]},
"curve":{a:[{tr:"i. eğri, viraj; f. eğri çizmek, kıvrılmak",ex:"Engineers designed the bridge to curve gently around the base of the mountain.",exTr:"Mühendisler köprüyü, dağın eteğinin çevresinde yumuşakça kıvrılacak şekilde tasarladı."}]},
"dart":{a:[{tr:"f. fırlamak, hızla hareket etmek",ex:"A small fish suddenly darted between the rocks to escape the approaching predator.",exTr:"Küçük bir balık, yaklaşan avcıdan kaçmak için kayaların arasına aniden fırladı.",yz:3},{tr:"i. dart oku, küçük ok",ex:"Players took turns throwing a dart at the target hanging on the wall.",exTr:"Oyuncular sırayla duvara asılı hedefe bir dart oku fırlattı.",yz:2}]},
"devoted":{a:[{tr:"s. adanmış, sadık, kendini vermiş",ex:"The scientist remained devoted to her research despite years of limited funding and setbacks.",exTr:"Bilim insanı, yıllarca süren sınırlı finansman ve aksiliklere rağmen araştırmasına adanmış kaldı."}]},
"disastrous":{a:[{tr:"s. felaket getiren, yıkıcı",ex:"The company's disastrous decision to ignore customer complaints led to a sharp drop in sales.",exTr:"Şirketin müşteri şikayetlerini görmezden gelme yönündeki yıkıcı kararı, satışlarda keskin bir düşüşe yol açtı."}]},
"drastically":{a:[{tr:"z. büyük ölçüde, sert biçimde",ex:"The government's new policy drastically reduced import taxes on renewable energy equipment.",exTr:"Hükümetin yeni politikası, yenilenebilir enerji ekipmanlarına uygulanan ithalat vergilerini büyük ölçüde azalttı."}]},
"embody":{a:[{tr:"f. somutlaştırmak, temsil etmek",ex:"The new museum was designed to embody the region's long artistic and cultural traditions.",exTr:"Yeni müze, bölgenin köklü sanatsal ve kültürel geleneklerini somutlaştıracak şekilde tasarlandı."}]},
"endless":{a:[{tr:"s. sonsuz, bitmez tükenmez",ex:"Researchers described the desert as an endless expanse of sand stretching beyond the horizon.",exTr:"Araştırmacılar çölü, ufkun ötesine uzanan sonsuz bir kum genişliği olarak tanımladı."}]},
"fruitful":{a:[{tr:"s. verimli, yararlı",ex:"The negotiations between the two companies proved fruitful, resulting in a long-term partnership.",exTr:"İki şirket arasındaki müzakereler verimli çıktı ve uzun vadeli bir ortaklıkla sonuçlandı."}]},
"full-term":{a:[{tr:"s. miadında, zamanında doğan",ex:"Most full-term babies are born after approximately forty weeks of pregnancy.",exTr:"Çoğu miadında bebek, gebeliğin yaklaşık kırkıncı haftasından sonra doğar."}]},
"generous":{a:[{tr:"s. cömert",ex:"A generous donor funded the entire renovation of the community library last spring.",exTr:"Cömert bir bağışçı, geçen bahar toplum kütüphanesinin tüm yenilenmesini finanse etti."}]},
"gentleman":{a:[{tr:"i. centilmen, kibar/nazik erkek; bey",ex:"The elderly gentleman politely offered his seat to a tired mother carrying a sleeping child.",exTr:"Yaşlı centilmen, uyuyan bir çocuğu taşıyan yorgun bir anneye nazikçe koltuğunu teklif etti."}]},
"gothic":{a:[{tr:"s. gotik",ex:"Tourists often admire the tall spires and pointed arches of gothic cathedrals across Europe.",exTr:"Turistler genellikle Avrupa'daki gotik katedrallerin yüksek kulelerine ve sivri kemerlerine hayran kalır."}]},
"grandmother":{a:[{tr:"i. büyükanne",ex:"Every summer, the children traveled to visit their grandmother in the countryside.",exTr:"Her yaz çocuklar, kırsalda yaşayan büyükannelerini ziyaret etmek için yolculuk yapardı."}]},
"harbor":{a:[{tr:"i. liman",ex:"Ships from several countries anchored in the harbor while waiting for the storm to pass.",exTr:"Fırtınanın geçmesini beklerken birçok ülkeden gelen gemiler limanda demir attı.",yz:4},{tr:"f. barındırmak, içinde taşımak (hastalık etkeni vb.)",ex:"Some patients harbor the bacteria for years without ever showing any symptoms of illness.",exTr:"Bazı hastalar, hiçbir hastalık belirtisi göstermeden bakteriyi yıllarca bünyelerinde barındırır.",yz:3}]},
"insomnia":{a:[{tr:"i. uykusuzluk",ex:"Chronic insomnia can significantly affect a person's concentration and overall physical health.",exTr:"Kronik uykusuzluk, bir insanın konsantrasyonunu ve genel fiziksel sağlığını önemli ölçüde etkileyebilir."}]},
"invert":{a:[{tr:"f. ters çevirmek",ex:"To read the message correctly, you must invert the image before printing it.",exTr:"Mesajı doğru okuyabilmek için görüntüyü yazdırmadan önce ters çevirmeniz gerekir."}]},
"koala":{a:[{tr:"i. koala",ex:"A koala can sleep for up to twenty hours a day, mostly in eucalyptus trees.",exTr:"Bir koala, günde yirmi saate kadar, çoğunlukla okaliptüs ağaçlarında uyuyabilir."}]},
"laser":{a:[{tr:"i. lazer",ex:"Surgeons now use a precise laser to perform delicate eye operations with minimal recovery time.",exTr:"Cerrahlar artık minimum iyileşme süresiyle hassas göz ameliyatları yapmak için hassas bir lazer kullanıyor."}]},
"liability":{a:[{tr:"i. yükümlülük, sorumluluk, borç",ex:"The contract clearly limits the company's liability in the event of accidental damage.",exTr:"Sözleşme, kazara oluşan hasar durumunda şirketin sorumluluğunu açıkça sınırlandırıyor."}]},
"life-threatening":{a:[{tr:"s. hayati tehlike oluşturan",ex:"Doctors warned that ignoring the infection could quickly develop into a life-threatening condition.",exTr:"Doktorlar, enfeksiyonun göz ardı edilmesi durumunda hızla hayati tehlike oluşturan bir duruma dönüşebileceği konusunda uyardı."}]},
"matter-of-fact":{a:[{tr:"s. duygusuz-nesnel, kuru, olduğu gibi anlatan (üslup)",ex:"The doctor explained the diagnosis in a calm, matter-of-fact tone that reassured the anxious family.",exTr:"Doktor, teşhisi endişeli aileyi rahatlatan sakin ve olgusal bir üslupla açıkladı."}]},
