"shook":{a:[{tr:"f. (shake'in geçmişi) salladı, sarstı",ex:"The explosion shook buildings several blocks away from the blast site.",exTr:"Patlama, patlama noktasından birkaç blok ötedeki binaları sarstı."}]},
"slang":{a:[{tr:"i. argo",ex:"Teenagers often invent new slang that older generations find difficult to understand.",exTr:"Gençler genellikle, yaşlı nesillerin anlamakta zorlandığı yeni argo sözcükler türetir."}]},
