"unrelated":{a:[{tr:"s. ilişkisiz, alakasız",ex:"The two research teams reached similar conclusions despite working on completely unrelated projects.",exTr:"İki araştırma ekibi, tamamen ilişkisiz projeler üzerinde çalışmasına rağmen benzer sonuçlara ulaştı."}]},
"victorious":{a:[{tr:"s. galip, muzaffer",ex:"The underdog team emerged victorious after a dramatic final match in the tournament.",exTr:"Şampiyonluğa aday görülmeyen takım, turnuvadaki dramatik final maçının ardından galip geldi."}]},
"yawn":{a:[{tr:"i. esneme; f. esnemek",ex:"The tired students tried to hide their yawns during the long afternoon lecture.",exTr:"Yorgun öğrenciler, uzun öğleden sonra dersinde esnemelerini gizlemeye çalıştı."}]},
"artefact":{a:[{tr:"i. eser, tarihi eser",ex:"Archaeologists discovered a bronze artefact buried deep beneath the ruins of the ancient temple.",exTr:"Arkeologlar, antik tapınağın kalıntılarının derinliklerinde gömülü bronz bir eser keşfetti."}]},
"bankrupt":{a:[{tr:"s. iflas etmiş",ex:"The airline was declared bankrupt after failing to recover from years of financial losses.",exTr:"Havayolu şirketinin, yıllarca süren mali kayıplardan kurtulamayınca iflası ilan edildi.",yz:4},{tr:"f. iflas ettirmek",ex:"Analysts warned that the lawsuit alone could bankrupt the small manufacturing company within months.",exTr:"Analistler, tek başına bu davanın küçük üretim şirketini birkaç ay içinde iflas ettirebileceği konusunda uyardı.",yz:2}]},
"basil":{a:[{tr:"i. fesleğen",ex:"The chef added fresh basil leaves to the sauce just before serving the pasta dish.",exTr:"Şef, makarna yemeğini servis etmeden hemen önce sosa taze fesleğen yaprakları ekledi."}]},
"chile":{a:[{tr:"i. acı biber",ex:"The recipe calls for one dried chile to add a subtle smoky heat to the stew.",exTr:"Tarif, yahniye hafif dumansı bir acılık katmak için bir adet kurutulmuş acı biber gerektiriyor."}]},
"compass":{a:[{tr:"i. pusula",ex:"Long before GPS technology existed, sailors relied on a simple compass to navigate the open sea.",exTr:"GPS teknolojisi var olmadan çok önce, denizciler açık denizde yön bulmak için basit bir pusulaya güvenirdi."}]},
"continental":{a:[{tr:"s. kıtasal, kıta ile ilgili",ex:"Geologists study continental drift to understand how landmasses have shifted over millions of years.",exTr:"Jeologlar, kara parçalarının milyonlarca yıl içinde nasıl kaydığını anlamak için kıtasal kaymayı incelerler."}]},
"debut":{a:[{tr:"i. ilk çıkış, debüt",ex:"The young violinist's debut at the concert hall received enthusiastic reviews from music critics.",exTr:"Genç kemancının konser salonundaki ilk çıkışı, müzik eleştirmenlerinden coşkulu yorumlar aldı.",yz:4},{tr:"f. ilk kez sahneye/piyasaya çıkmak",ex:"The company will debut its new electric vehicle at the international auto show next month.",exTr:"Şirket, yeni elektrikli aracını gelecek ay uluslararası otomobil fuarında piyasaya çıkaracak.",yz:3}]},
"disappointing":{a:[{tr:"s. hayal kırıklığı yaratan, umulanın altında",ex:"The company's quarterly earnings report was disappointing compared to what investors had expected.",exTr:"Şirketin üç aylık kazanç raporu, yatırımcıların beklediğinin altında, hayal kırıklığı yarattı."}]},
"disturbing":{a:[{tr:"s. rahatsız edici, kaygı verici",ex:"The documentary revealed disturbing details about conditions inside the abandoned factory.",exTr:"Belgesel, terk edilmiş fabrikanın içindeki koşullar hakkında rahatsız edici ayrıntılar ortaya çıkardı."}]},
"dot":{a:[{tr:"i. nokta",ex:"Small red dots on the map indicated the location of every reported earthquake that year.",exTr:"Haritadaki küçük kırmızı noktalar, o yıl bildirilen her depremin yerini gösteriyordu."}]},
"ego":{a:[{tr:"i. benlik, ego",ex:"Psychologists argue that a fragile ego can make constructive criticism difficult to accept.",exTr:"Psikologlar, kırılgan bir egonun yapıcı eleştiriyi kabul etmeyi zorlaştırabileceğini savunuyor."}]},
"elect":{a:[{tr:"f. seçmek",ex:"Members of the academy gather every spring to elect a president who will represent them for three years.",exTr:"Akademi üyeleri, kendilerini üç yıl boyunca temsil edecek bir başkan seçmek için her bahar bir araya gelir.",yz:4},{tr:"s. seçilmiş (henüz göreve başlamamış)",ex:"Officials introduced the senator elect at a formal ceremony held before the inauguration.",exTr:"Yetkililer, göreve başlama töreninden önce düzenlenen resmi bir seremonide seçilmiş senatörü tanıttı.",yz:1}]},
"emotionally":{a:[{tr:"z. duygusal olarak",ex:"The counselor explained that children who witness conflict at home often struggle emotionally later in life.",exTr:"Danışman, evde çatışmaya tanık olan çocukların hayatlarının ilerleyen dönemlerinde duygusal olarak zorlandığını açıkladı."}]},
"enthusiasm":{a:[{tr:"i. coşku, heves, şevk",ex:"The new teacher's enthusiasm for science inspired many students to pursue careers in research.",exTr:"Yeni öğretmenin bilime olan coşkusu, birçok öğrenciyi araştırma alanında kariyer yapmaya teşvik etti."}]},
"equation":{a:[{tr:"i. denklem",ex:"Students spent the entire class trying to solve a complex equation involving several variables.",exTr:"Öğrenciler, birkaç değişken içeren karmaşık bir denklemi çözmeye çalışarak tüm dersi geçirdi.",yz:4},{tr:"i. eşitleme, bir tutma",ex:"Many economists reject the simple equation of economic growth with overall social progress.",exTr:"Birçok ekonomist, ekonomik büyümenin genel toplumsal ilerlemeyle eşitlenmesini reddeder.",yz:2}]},
"extinguish":{a:[{tr:"f. söndürmek, bastırmak",ex:"Firefighters worked for hours to extinguish the blaze that had spread across the dry forest.",exTr:"İtfaiyeciler, kuru ormana yayılan yangını söndürmek için saatlerce çalıştı."}]},
"foresee":{a:[{tr:"f. önceden görmek, öngörmek",ex:"Few analysts could foresee how quickly the pandemic would transform global supply chains.",exTr:"Çok az analist, pandeminin küresel tedarik zincirlerini bu kadar hızlı dönüştüreceğini öngörebildi."}]},
"geology":{a:[{tr:"i. jeoloji",ex:"Students majoring in geology often spend summers collecting rock samples in remote areas.",exTr:"Jeoloji bölümünde okuyan öğrenciler, yazlarını genellikle uzak bölgelerde kaya örnekleri toplayarak geçirir."}]},
"headline":{a:[{tr:"i. başlık, manşet",ex:"The newspaper's front-page headline announced the discovery of a new renewable energy source.",exTr:"Gazetenin ön sayfa manşeti, yeni bir yenilenebilir enerji kaynağının keşfedildiğini duyurdu.",yz:4},{tr:"f. manşetlerde yer almak, baş haber olmak",ex:"The scandal continued to headline the evening news for nearly two weeks straight.",exTr:"Skandal, neredeyse iki hafta boyunca aralıksız akşam haberlerinde manşetlerde yer almaya devam etti.",yz:2}]},
"hi-tech":{a:[{tr:"s. yüksek teknolojili, ileri teknoloji",ex:"The new hospital wing is equipped with hi-tech scanners that detect diseases at early stages.",exTr:"Yeni hastane bölümü, hastalıkları erken evrelerde tespit eden yüksek teknolojili tarayıcılarla donatılmıştır."}]},
"hierarchical":{a:[{tr:"s. hiyerarşik, aşamalı",ex:"The company recently replaced its rigid hierarchical structure with a more flexible team-based approach.",exTr:"Şirket, katı hiyerarşik yapısını yakın zamanda daha esnek, ekip temelli bir yaklaşımla değiştirdi."}]},
