"accountant":{a:[{tr:"i. muhasebeci",ex:"The small business hired an accountant to manage its taxes and monthly financial records.",exTr:"Küçük işletme, vergilerini ve aylık mali kayıtlarını yönetmek için bir muhasebeci işe aldı."}]},
"beta":{a:[{tr:"i. beta sürümü, deneme sürümü",ex:"Thousands of users signed up to test the beta version of the new operating system.",exTr:"Binlerce kullanıcı, yeni işletim sisteminin beta sürümünü test etmek için kaydoldu."}]},
"charismatic":{a:[{tr:"s. karizmatik",ex:"Historians credit the movement's rapid growth to its charismatic and highly persuasive founder.",exTr:"Tarihçiler, hareketin hızlı büyümesini karizmatik ve son derece ikna edici kurucusuna bağlıyor."}]},
"cheek":{a:[{tr:"i. yanak",ex:"The toddler proudly showed off the small scrape on her cheek from the playground fall.",exTr:"Küçük çocuk, oyun parkında düşmesinden kalan yanağındaki küçük sıyrığı gururla gösterdi."}]},
"cholera":{a:[{tr:"i. kolera",ex:"Poor sanitation after the flood led to a sudden outbreak of cholera in the region.",exTr:"Sel sonrasındaki yetersiz hijyen koşulları, bölgede ani bir kolera salgınına yol açtı."}]},
