"congress":{a:[{tr:"i. kongre, meclis",ex:"The bill must pass through both chambers of congress before it can become law.",exTr:"Tasarının yasalaşabilmesi için kongrenin her iki kanadından da geçmesi gerekir."}]},
"continuation":{a:[{tr:"i. devam, süreklilik",ex:"The peace talks are seen as a natural continuation of negotiations that began over a decade ago.",exTr:"Barış görüşmeleri, on yıldan uzun süre önce başlayan müzakerelerin doğal bir devamı olarak görülüyor."}]},
