"intensely":{a:[{tr:"z. yoğun biçimde, şiddetle",ex:"Scientists studied how intensely focused meditation can alter brain activity over several months.",exTr:"Bilim insanları, yoğun biçimde odaklanmış meditasyonun aylar içinde beyin etkinliğini nasıl değiştirebileceğini araştırdı."}]},
"loser":{a:[{tr:"i. kaybeden",ex:"Economists identified small manufacturers as the biggest losers in the recent trade agreement.",exTr:"Ekonomistler, küçük üreticileri son ticaret anlaşmasının en büyük kaybedenleri olarak tanımladı."}]},
"meteor":{a:[{tr:"i. meteor, göktaşı",ex:"Astronomers recorded an unusually bright meteor streaking across the night sky over the desert.",exTr:"Gökbilimciler, çölün üzerindeki gece gökyüzünde parlayarak geçen alışılmadık derecede parlak bir meteoru kaydetti."}]},
"mindless":{a:[{tr:"s. düşüncesiz, aptalca",ex:"Critics described the film's plot as mindless entertainment lacking any real depth or message.",exTr:"Eleştirmenler, filmin konusunu gerçek bir derinlik ya da mesajdan yoksun, düşüncesiz bir eğlence olarak tanımladı."}]},
"mum":{a:[{tr:"s. sessiz, ağzı sıkı",ex:"Witnesses agreed to stay mum about the details of the negotiation until the deal closed.",exTr:"Tanıklar, anlaşma kapanana kadar müzakerenin ayrıntıları hakkında sessiz kalmayı kabul etti.",yz:3},{tr:"i. anne",ex:"In the British sitcom, the teenager constantly argues with her mum about household chores.",exTr:"İngiliz durum komedisinde genç kız, ev işleri konusunda annesiyle sürekli tartışır.",yz:2}]},
"outburst":{a:[{tr:"i. ani patlama, taşkınlık",ex:"The coach's sudden outburst during the press conference surprised journalists who expected a calm response.",exTr:"Antrenörün basın toplantısı sırasındaki ani öfke patlaması, sakin bir yanıt bekleyen gazetecileri şaşırttı."}]},
"primate":{a:[{tr:"i. primat",ex:"Researchers observed that primates use simple tools to extract insects from tree bark.",exTr:"Araştırmacılar, primatların ağaç kabuğundan böcek çıkarmak için basit aletler kullandığını gözlemledi.",yz:4},{tr:"i. baş piskopos, kilise lideri",ex:"The primate of the church delivered a solemn address during the cathedral's anniversary ceremony.",exTr:"Kilisenin baş piskoposu, katedralin yıldönümü töreninde ciddi bir konuşma yaptı.",yz:1}]},
"reap":{a:[{tr:"f. elde etmek, kazanmak",ex:"Companies that invest early in employee training often reap significant benefits in productivity later.",exTr:"Çalışan eğitimine erken yatırım yapan şirketler, daha sonra üretkenlikte önemli faydalar elde eder.",yz:4},{tr:"f. hasat etmek, biçmek",ex:"Farmers traditionally reap wheat in late summer before the first autumn storms arrive.",exTr:"Çiftçiler geleneksel olarak, ilk sonbahar fırtınaları gelmeden önce buğdayı yaz sonunda hasat eder.",yz:2}]},
"recurring":{a:[{tr:"s. tekrarlayan, yinelenen",ex:"Doctors advised the patient to keep a journal to track her recurring headaches over time.",exTr:"Doktorlar, hastaya tekrarlayan baş ağrılarını zaman içinde takip etmesi için bir günlük tutmasını önerdi."}]},
"relentless":{a:[{tr:"s. amansız, yılmaz",ex:"Firefighters battled the relentless flames for nearly twelve hours before finally containing the wildfire.",exTr:"İtfaiyeciler, orman yangınını sonunda kontrol altına almadan önce amansız alevlerle neredeyse on iki saat mücadele etti."}]},
"retired":{a:[{tr:"s. emekli",ex:"Many retired engineers volunteer their expertise to help local schools with science programs.",exTr:"Birçok emekli mühendis, yerel okullara fen programlarında bilgi birikimiyle gönüllü olarak yardım eder."}]},
