"sore":{a:[{tr:"s. ağrılı, acıyan",ex:"After the long hike, her muscles felt sore and she needed several days to recover.",exTr:"Uzun yürüyüşten sonra kasları ağrıyordu ve toparlanmak için birkaç güne ihtiyaç duydu.",yz:3},{tr:"i. yara, ağrılı yer (deride)",ex:"The nurse applied ointment to the sore on the patient's heel to prevent infection.",exTr:"Hemşire, enfeksiyonu önlemek için hastanın topuğundaki yaraya merhem sürdü.",yz:2}]},
"speciality":{a:[{tr:"i. uzmanlık alanı, ihtisas",ex:"The surgeon chose cardiology as her speciality after completing several years of general training.",exTr:"Cerrah, birkaç yıllık genel eğitimini tamamladıktan sonra kardiyolojiyi uzmanlık alanı olarak seçti.",yz:3},{tr:"i. özel ürün, yöresel lezzet",ex:"Grilled seafood is a local speciality that visitors are encouraged to try at the harbor restaurants.",exTr:"Izgara deniz ürünleri, ziyaretçilerin liman restoranlarında denemesi tavsiye edilen yöresel bir lezzettir.",yz:2}]},
